<template><view class="page"><view class="row-between"><view class="page-title">车辆信息</view><button v-if="creator" size="mini" class="mini-primary" @click="add">发布车辆</button></view><view v-for="v in list" :key="v.id" class="card"><view class="section-title">{{ v.plateNumber }}</view><view>司机：{{ v.driverName }}</view><view>上车：{{ displayTime(v.pickupTime) }}</view><view>地点：{{ v.pickupLocation }}</view></view><view v-if="!list.length" class="empty">暂未发布车辆信息</view></view></template>
<script setup lang="ts">import{ref}from'vue';import{onLoad,onShow}from'@dcloudio/uni-app';import{api}from'@/services/api';import{displayTime}from'@/utils/time';import type{Vehicle}from'@/services/types';const id=ref(0),creator=ref(false),list=ref<Vehicle[]>([]);onLoad((o:any)=>{id.value=Number(o.id);creator.value=o.creator==='1'});onShow(async()=>{if(id.value)list.value=await api(`/activities/${id.value}/vehicles`)});const add=()=>uni.navigateTo({url:`/pages/vehicleAdd/vehicleAdd?id=${id.value}`})</script>
